const src = $('Only rows without video').first().json;
const cfg = $('Video settings').first().json;
const res = $input.first().json;
const BS = String.fromCharCode(92);

const ws = (t) => Array.from(String(t == null ? '' : t)).map(c => (c.charCodeAt(0) <= 32 ? ' ' : c)).join('').split(' ').filter(Boolean).join(' ');
const strip = (t, open, close) => { let out = '', depth = 0; for (const ch of String(t == null ? '' : t)) { if (ch === open) depth++; else if (ch === close) { if (depth > 0) depth--; else out += ch; } else if (depth === 0) out += ch; } return out; };
const noBraces = (t) => String(t == null ? '' : t).split('{').join(' ').split('}').join(' ');
const clean = (v, max) => ws(noBraces(v).split('"').join(' ').split(BS).join(' ')).slice(0, max);

let data = null;
if (res && Array.isArray(res.scenes)) {
  data = res;
} else {
  let raw = res?.choices?.[0]?.message?.content ?? res.content?.parts?.[0]?.text ?? res.parts?.[0]?.text ?? res.text ?? res.output ?? '';
  if (typeof raw !== 'string') raw = JSON.stringify(raw);
  raw = raw.split('```json').join('').split('```').join('').trim();
  try {
    data = JSON.parse(raw);
  } catch (e) {
    const found = [];
    const re = /[{][^{}]*"narration"[^{}]*[}]/g;
    let m;
    while ((m = re.exec(raw)) !== null) { try { found.push(JSON.parse(m[0])); } catch (_) {} }
    const pick = (k) => {
      const i = raw.indexOf('"' + k + '"');
      if (i < 0) return '';
      let j = raw.indexOf(':', i);
      if (j < 0) return '';
      j = raw.indexOf('"', j);
      if (j < 0) return '';
      let out = '';
      for (let p = j + 1; p < raw.length; p++) {
        const ch = raw[p];
        if (ch === BS) { out += raw[p + 1] || ''; p++; continue; }
        if (ch === '"') break;
        out += ch;
      }
      return out;
    };
    data = { title: pick('title'), thumbnail_text: pick('thumbnail_text'), language: pick('language') || 'en', music_mood: pick('music_mood'), scenes: found };
  }
}

const scenes = (data.scenes || []).map(s => {
  const kw = ws(s.keywords || 'nature landscape');
  const alt = ws(s.alt_keywords || String(s.keywords || 'nature').split(' ')[0] || 'nature');
  const queries = (Array.isArray(s.queries) ? s.queries : []).map(q => clean(q, 60)).filter(Boolean).slice(0, 5);
  return {
    narration: ws(noBraces(strip(strip(s.narration, '(', ')'), '[', ']'))),
    keywords: kw,
    alt_keywords: alt,
    visual: clean(s.visual, 160),
    queries: queries.length ? queries : [kw, alt].filter(Boolean),
    text: clean(s.text, 40),
    visual_type: String(s.visual_type || '').toLowerCase() === 'animation' ? 'animation' : 'footage',
    image_prompt: clean(s.image_prompt, 220)
  };
}).filter(s => s.narration.length > 20);

const want = Number(cfg.scene_count) || 0;
if (scenes.length < Math.max(3, Math.floor(want * 0.8))) {
  throw new Error('Gemini returned ' + scenes.length + ' of ' + want + ' scenes (answer was cut off). It will retry on the next run.');
}

const moods = ['calm', 'dramatic', 'uplifting', 'mysterious', 'inspiring'];
const mood = moods.includes(String(data.music_mood || '').toLowerCase()) ? String(data.music_mood).toLowerCase() : 'calm';

return scenes.map((s, i) => ({ json: {
  row_number: src.row_number,
  prompt: src.PROMPT,
  title: data.title || String(src.PROMPT).slice(0, 60),
  thumbnail_text: data.thumbnail_text || '',
  language: data.language || 'en',
  music_mood: mood,
  scene_idx: i,
  narration: s.narration,
  keywords: s.keywords,
  alt_keywords: s.alt_keywords,
  visual: s.visual,
  queries: s.queries,
  text: s.text,
  visual_type: s.visual_type,
  image_prompt: s.image_prompt
} }));

const scenes = $('Parse script').all();
const pool = $('Build clip candidates').first().json.pool || [];
const photopool = $('Build clip candidates').first().json.photos || [];
const cfg = $('Video settings').first().json;
const st = $('Studio settings').first().json;
const f = scenes[0].json;
const lang = String(f.language || 'en').toLowerCase().slice(0, 2);
const voices = { en: 'en-US-AndrewMultilingualNeural', bn: 'bn-BD-NabanitaNeural', hi: 'hi-IN-MadhurNeural', ur: 'ur-PK-AsadNeural', ar: 'ar-SA-HamedNeural' };
const voice = cfg.voice_override || voices[lang] || voices.en;
const hd = String(cfg.resolution) === '1080';

// 1) Clips: the AI editor's picks first, then the best keyword matches
let picks = {}; let photoPicks = {};
try {
  const res = $('Pick best clips').first().json;
  let d = Array.isArray(res.scenes) ? res : null;
  if (!d) {
    let raw = res?.choices?.[0]?.message?.content ?? res.content?.parts?.[0]?.text ?? res.text ?? res.output ?? '';
    if (typeof raw !== 'string') raw = JSON.stringify(raw);
    const m = raw.split('```json').join('').split('```').join('').match(/[{][^]*[}]/);
    d = m ? JSON.parse(m[0]) : null;
  }
  for (const s of (d?.scenes || [])) {
    picks[Number(s.i)] = (Array.isArray(s.picks) ? s.picks : []).map(Number).filter(n => Number.isInteger(n));
    photoPicks[Number(s.i)] = (Array.isArray(s.photos) ? s.photos : []).map(Number).filter(n => Number.isInteger(n));
  }
} catch (e) { picks = {}; photoPicks = {}; }

const used = new Set();
const photoUsed = new Set();
const out = scenes.map((s, i) => {
  const cands = pool[i] || [];
  const picked = (picks[i] || []).map(j => cands[j]).filter(Boolean);
  const curated = Object.prototype.hasOwnProperty.call(picks, i);
  const rest = cands.filter(c => !picked.includes(c) && (!curated || c.score >= 3));
  const list = [...picked, ...rest];
  let clips = list.filter(c => !used.has(c.url)).slice(0, 3).map(c => c.url);
  if (clips.length < 2) clips = clips.concat(list.filter(c => !clips.includes(c.url)).slice(0, 3 - clips.length).map(c => c.url));
  clips.forEach(u => used.add(u));
  const pcands = photopool[i] || [];
  const ppicked = (photoPicks[i] || []).map(j => pcands[j]).filter(Boolean);
  const plist = [...ppicked, ...pcands.filter(c => !ppicked.includes(c))];
  let scene_photos = plist.filter(c => !photoUsed.has(c.url)).slice(0, 2).map(c => c.url);
  scene_photos.forEach(u => photoUsed.add(u));
  return {
    narration: s.json.narration,
    clips,
    photos: scene_photos,
    visual: s.json.visual || '',
    queries: Array.isArray(s.json.queries) ? s.json.queries : [],
    keywords: s.json.keywords || '',
    alt_keywords: s.json.alt_keywords || '',
    text: s.json.text || '',
    visual_type: s.json.visual_type || 'footage',
    image_prompt: s.json.image_prompt || ''
  };
});

// scenes with no footage borrow from the nearest scene that has some
for (let i = 0; i < out.length; i++) {
  if (out[i].clips.length) continue;
  for (let d = 1; d < out.length; d++) {
    const n = out[i - d]?.clips.length ? out[i - d] : out[i + d];
    if (n && n.clips.length) { out[i].clips = n.clips.slice(0, 2); break; }
  }
}
// The render always falls back to free Pollinations AI images (no key needed),
// so an empty footage list is only fatal when AI images are also disabled.
const studioCanSearch = st.studio_vision !== false || st.studio_ai_images !== false;
if (!out.some(s => s.clips.length) && !studioCanSearch) {
  throw new Error('No stock clips found. Add a valid pexels_key and/or pixabay_key in the Video settings node.');
}

// 2) Duration: fit the speaking speed so the video matches the target length
const wordsOf = (t) => String(t || '').split(' ').filter(Boolean).length;
const totalWords = out.reduce((n, s) => n + wordsOf(s.narration), 0);
const wps = ({ en: 2.5, hi: 2.4, ur: 2.4, ar: 2.3, bn: 2.2 })[lang] || 2.4; // spoken words per second at normal speed
const targetSec = (Number(cfg.target_minutes) || 0) * 60;
const normalSec = totalWords / wps;
const userRate = !!cfg.voice_rate && cfg.voice_rate !== '+0%';
let rateNum = 0;
if (!userRate && targetSec > 0) {
  const adj = Math.round((normalSec / targetSec - 1) * 100);
  rateNum = Math.abs(adj) < 4 ? 0 : Math.max(-25, Math.min(25, adj));
}
const rate = userRate ? cfg.voice_rate : (rateNum >= 0 ? '+' : '') + rateNum + '%';
const estSec = normalSec / (1 + (userRate ? (parseInt(cfg.voice_rate, 10) || 0) : rateNum) / 100);
if (targetSec > 0 && Math.abs(estSec / targetSec - 1) > 0.3) {
  throw new Error('Script length is off: ' + totalWords + ' words is about ' + (estSec / 60).toFixed(1) + ' min, target is ' + (targetSec / 60) + ' min. Run again (the script is rewritten) or change DURATION.');
}

const plan = {
  job_id: 'v' + Date.now().toString(36) + 'r' + f.row_number,
  voice, rate, language: lang,
  resolution: hd ? '1080' : '720',
  format: cfg.format || '16:9',
  music_mood: f.music_mood, music_volume: Number(cfg.music_volume) || 0.3,
  captions: cfg.captions !== false,
  title: f.title, thumbnail_text: f.thumbnail_text,
  resume_url: $execution.resumeUrl,
  studio: {
    vision: st.studio_vision !== false,
    ai_images: st.studio_ai_images !== false,
    max_ai_images: Number(st.studio_max_ai_images) >= 0 ? Number(st.studio_max_ai_images) : 8,
    animations: st.studio_animations !== false,
    sfx: st.studio_sfx !== false
  },
  ai_images: st.studio_ai_images !== false,
  image_max: Number(st.studio_max_ai_images) >= 0 ? Number(st.studio_max_ai_images) : 8,
  quality: 'best',
  scenes: out
};
let plan_json = JSON.stringify(plan);
// GitHub accepts a limited input size: shrink the footage lists before giving up
if (plan_json.length > 52000) {
  plan.scenes = plan.scenes.map(s => ({ ...s, clips: s.clips.slice(0, 2), photos: (s.photos || []).slice(0, 1) }));
  plan_json = JSON.stringify(plan);
}
if (plan_json.length > 60000) throw new Error('Plan too large for GitHub dispatch: ' + plan_json.length + '. Use a shorter DURATION or fewer scenes.');

const digest = out.map(s => String(s.narration).split(' ').slice(0, 18).join(' ')).join(' | ').slice(0, 3500);
return [{ json: { job_id: plan.job_id, plan_json, github_repo: cfg.github_repo, github_ref: cfg.github_ref || 'v22', row_number: f.row_number, prompt: f.prompt, title: f.title, language: lang, digest, scene_count: out.length, voice, rate, est_seconds: Math.round(estSec), target_seconds: Math.round(targetSec), total_words: totalWords } }];

const empty = (v) => v === undefined || v === null || String(v).trim() === '';

// The sheet headers may be written in any case (prompt / PROMPT, video / VIDEO ...).
// Add an UPPERCASE copy of every column so the rest of the workflow always finds them.
const rows = $input.all().map(i => {
  const o = { ...i.json };
  for (const [k, v] of Object.entries(i.json)) {
    if (k === 'row_number') continue;
    const U = String(k).trim().toUpperCase();
    if (!(U in o)) o[U] = v;
  }
  return o;
});

// Pressing 'Start manually' is a deliberate human action: it may take over a row stuck on 'processing'.
let manual = false;
try { manual = $('Start manually').isExecuted === true; } catch (e) { manual = false; }

// A row stuck on 'processing' (run cancelled, n8n restarted, render crashed...) must never block the sheet.
// Scheduled runs: 'processing <ISO time>' older than 2 hours (or with no time) counts as stale.
const STALE_MS = 2 * 60 * 60 * 1000;
const isStale = (status) => {
  const s = String(status || '').trim().toLowerCase();
  if (!s.startsWith('processing')) return false;
  if (manual) return true;
  const m = s.match(/\d{4}-\d{2}-\d{2}t[\d:.]+z/);
  if (!m) return true;
  const t = Date.parse(m[0].toUpperCase());
  return isNaN(t) || (Date.now() - t) > STALE_MS;
};

const ok = rows.filter(r =>
  !empty(r.PROMPT) &&
  empty(r.VIDEO) &&
  (empty(r.STATUS) || String(r.STATUS).toLowerCase().startsWith('retry') || isStale(r.STATUS))
);

// Nothing to do is NOT an error: end the run quietly (no red node, no error mail).
if (!ok.length) return [];

// one video per run
return ok.slice(0, 1).map(r => ({ json: r }));

const base = $('Collect video plan').first().json;
const res = $input.first().json;
let d = {};
if (Array.isArray(res.titles)) {
  d = res;
} else {
  let raw = res?.choices?.[0]?.message?.content ?? res.content?.parts?.[0]?.text ?? res.text ?? res.output ?? '';
  if (typeof raw !== 'string') raw = JSON.stringify(raw);
  raw = raw.replace(/```json|```/g, '').trim();
  try { d = JSON.parse(raw); } catch (e) {
    const m = raw.match(/\{[\s\S]*\}/);
    if (m) { try { d = JSON.parse(m[0]); } catch (_) {} }
  }
}
const titles = (Array.isArray(d.titles) ? d.titles : []).filter(t => typeof t === 'string' && t.length > 5 && t.length <= 95);
const tags = (Array.isArray(d.tags) ? d.tags : []).map(t => String(t).replace(/[#,]/g, '').trim()).filter(Boolean);
let tagStr = '';
for (const t of tags) { if ((tagStr + ',' + t).length > 450) break; tagStr += (tagStr ? ',' : '') + t; }
const hashtags = (Array.isArray(d.hashtags) ? d.hashtags : []).slice(0, 3).map(h => '#' + String(h).replace(/[#\s]/g, '')).join(' ');
const description = [String(d.description || '').trim(), hashtags].filter(Boolean).join('\n\n');
return [{ json: { title: titles[0] || base.title, description: description || base.title, tags: tagStr, pinned_comment: String(d.pinned_comment || '') } }];

const scenes = $('Parse script').all();
const pxa = $('Find Pexels clip').all();
const pxb = $('Find Pexels alt clip').all();
const wkv = $('Find Wikimedia video').all();
const pxv = $('Find Pixabay clips').all();
const pbx = $('Find Pixabay photos').all();
const wkm = $('Find Wikimedia photos').all();
const pbp = $('Find Pexels photos').all();
const cfg = $('Video settings').first().json;
const hd = String(cfg.resolution) === '1080';
const fmt = String(cfg.format || '16:9');
const target = hd ? 1920 : 1280;

const words = (s) => String(s || '').toLowerCase().replace(/[^a-z0-9 ]/g, ' ').split(/\s+/).filter(w => w.length > 2);
const orientOk = (w, h) => { if (!w || !h) return true; if (fmt === '9:16') return h >= w; if (fmt === '1:1') return true; return w >= h; };
const side = (v) => Math.max(v.width || 0, v.height || 0);
const pickVariant = (list) => {
  const ok = list.filter(v => v && v.url && orientOk(v.width, v.height));
  if (!ok.length) return null;
  ok.sort((a, b) => (Math.abs(side(a) - target) - Math.abs(side(b) - target)) || ((a.size || 0) - (b.size || 0)));
  return ok[0];
};

const fromPexels = (item) => (item?.json?.videos || []).map(v => {
  const files = (v.video_files || []).filter(x => x.file_type === 'video/mp4' && x.link).map(x => ({ url: x.link, width: x.width, height: x.height, size: 0 }));
  const f = pickVariant(files);
  if (!f) return null;
  const dur = Number(v.duration) || 0;
  if (dur && dur < 4) return null;
  const slug = (String(v.url || '').split('/video/')[1] || '').replace(/[-\/]/g, ' ').replace(/\d+/g, ' ').trim();
  return { url: f.url, dur, tags: slug, type: 'film', src: 'pexels' };
}).filter(Boolean);

const fromWikimediaVideo = (item) => {
  const raw = item?.json?.query?.pages;
  const pages = Array.isArray(raw) ? raw : Object.values(raw || {});
  return pages.map(p => {
    const ii = (p.imageinfo || [])[0];
    if (!ii || !ii.url) return null;
    if (!/^video\//i.test(String(ii.mime || ''))) return null;
    if ((ii.width || 0) < 480) return null;
    if ((ii.size || 0) > 80 * 1024 * 1024) return null;   // skip huge files, slow to download
    const title = String(p.title || '').replace(/^File:/i, '').replace(/\.[a-z0-9]+$/i, '').replace(/[-_]/g, ' ');
    return { url: ii.url.split('?')[0], dur: Number(ii.duration) || 0, tags: title.slice(0, 120), type: 'film', src: 'wikimedia' };
  }).filter(Boolean);
};

const fromPixabayVideo = (item) => (item?.json?.hits || []).map(h => {
  const v = h.videos || {};
  const variants = ['large', 'medium', 'small'].map(k => v[k] && { url: v[k].url, width: v[k].width, height: v[k].height, size: 0 }).filter(Boolean);
  const f = pickVariant(variants);
  if (!f) return null;
  const dur = Number(f.dur ?? h.duration) || 0;
  if (dur && dur < 4) return null;
  return { url: f.url, dur, tags: String(h.tags || ''), type: 'film', src: 'pixabay' };
}).filter(Boolean);

const fromPixabayPhotos = (item) => (item?.json?.hits || [])
  .filter(h => h.largeImageURL)
  .map(h => ({ url: h.largeImageURL, dur: 0, tags: String(h.tags || ''), type: 'photo', src: 'pixabay-photo' }));

const fromWikimedia = (item) => {
  const raw = item?.json?.query?.pages;
  const pages = Array.isArray(raw) ? raw : Object.values(raw || {});
  return pages.map(p => {
    const ii = (p.imageinfo || [])[0];
    if (!ii || !ii.thumburl) return null;
    if (!/jpe?g|png/i.test(String(ii.mime || ''))) return null;
    if ((ii.thumbwidth || ii.width || 0) < 800) return null;
    const title = String(p.title || '').replace(/^File:/i, '').replace(/\.[a-z]+$/i, '').replace(/[-_]/g, ' ').replace(/\d{3,}px/g, ' ');
    return { url: ii.thumburl, dur: 0, tags: title.slice(0, 120), type: 'photo', src: 'wikimedia' };
  }).filter(Boolean);
};

const fromPexelsPhotos = (item) => (item?.json?.photos || []).map(p => {
  const url = p?.src?.large2x || p?.src?.large || p?.src?.original;
  if (!url) return null;
  return { url, dur: 0, tags: [p.alt, p.photographer].filter(Boolean).join(' '), type: 'photo', src: 'pexels-photo' };
}).filter(Boolean);

const score = (c, kw, alt) => {
  const tags = words(c.tags);
  const hit = (list) => list.filter(w => tags.some(t => t === w || t.startsWith(w) || w.startsWith(t))).length;
  return hit(words(kw)) * 3 + hit(words(alt)) * 1.5 + (c.dur >= 8 ? 1 : 0) + (c.dur >= 5 ? 0.5 : 0) - (c.type === 'animation' ? 1.5 : 0);
};

const dedupe = (all) => {
  const seen = new Set();
  return all.filter(c => (seen.has(c.url) ? false : (seen.add(c.url), true)));
};

const pool = scenes.map((s, i) => {
  const kw = s.json.keywords, alt = s.json.alt_keywords;
  const all = [...fromPexels(pxa[i]), ...fromPexels(pxb[i]), ...fromPixabayVideo(pxv[i]), ...fromWikimediaVideo(wkv[i])];
  return dedupe(all)
    .map(c => ({ ...c, score: score(c, kw, alt) }))
    .sort((a, b) => b.score - a.score)
    .slice(0, 10);
});

const photos = scenes.map((s, i) => {
  const kw = s.json.keywords, alt = s.json.alt_keywords;
  const all = [...fromWikimedia(wkm[i]), ...fromPexelsPhotos(pbp[i]), ...fromPixabayPhotos(pbx[i])];
  return dedupe(all)
    .map(c => ({ ...c, score: score(c, kw, alt) }))
    .sort((a, b) => b.score - a.score)
    .slice(0, 6);
});

const curator_input = scenes.map((s, i) => {
  const vLines = (pool[i] || []).map((c, j) => '  V' + j + ') ' + c.tags.slice(0, 80) + ' | ' + Math.round(c.dur) + 's video (' + c.src + ')');
  const pLines = (photos[i] || []).map((c, j) => '  P' + j + ') ' + c.tags.slice(0, 80) + ' | photo (' + c.src + ')');
  return 'SCENE ' + i + ': ' + String(s.json.narration).slice(0, 220) + '\n' + (vLines.length ? vLines.join('\n') : '  (no video candidates)') + '\n' + (pLines.length ? pLines.join('\n') : '  (no photo candidates)');
}).join('\n\n');

return [{ json: { pool, photos, curator_input, scene_count: scenes.length } }];

// 2 minute safety margin for clock differences between n8n and GitHub
const started = new Date(Date.now() - 120000).toISOString().replace(/\.\d+Z$/, 'Z');
return [{ json: { started_at: started } }];

const res = $input.first().json;
const plan = $('Collect video plan').first().json;
const started = new Date($('Set start time').first().json.started_at);
// 170 checks x 2 min = 340 min. The GitHub job timeout on branch v22 is 330 min, so a render can never finish after we gave up.
const MAX_CHECKS = 170;
const attempt = $runIndex + 1;

// If GitHub answered with an error this time (rate limit, 5xx), res has no workflow_runs: just poll again.
const runs = Array.isArray(res.workflow_runs) ? res.workflow_runs : [];
const recent = runs.filter(r => new Date(r.created_at) >= started);
// prefer a run whose title/name contains our job id, otherwise the oldest run after dispatch
const mine = recent.filter(r => JSON.stringify([r.name, r.display_title, r.run_number]).includes(plan.job_id));
const pool = (mine.length ? mine : recent).sort((a, b) => new Date(a.created_at) - new Date(b.created_at));
const run = pool[0];
const fallbackUrl = 'https://github.com/' + plan.github_repo + '/actions';

if (run && run.status === 'completed') {
  return [{ json: { done: true, attempt, body: { status: run.conclusion || 'failure', run_url: run.html_url || fallbackUrl, run_id: run.id } } }];
}
if (attempt >= MAX_CHECKS) {
  return [{ json: { done: true, attempt, body: { status: 'timeout', run_url: (run && run.html_url) || fallbackUrl, run_id: run ? run.id : null } } }];
}
return [{ json: { done: false, attempt, body: { status: run ? run.status : 'waiting_for_run', run_url: (run && run.html_url) || fallbackUrl, run_id: run ? run.id : null } } }];

const base = $input.first().json;
const row = $('Only rows without video').first().json;
const lower = (v) => String(v == null ? '' : v).trim().toLowerCase();
const styles = ['documentary', 'presenter', 'podcast', 'cartoon', 'animation', '2d', '3d'];
let style = lower(row.STYLE);
if (!styles.includes(style)) style = 'documentary';
const male = /andrew|christopher|pradeep|guy|madhur|asad|hamed|brian/.test(lower(base.voice));
const valid = ['girl-1', 'boy-1', 'cartoon-boy-1', 'cartoon-girl-1', 'robot-1', 'grandpa-1', 'kid-boy-1', 'bizman-1'];
let avatar = lower(row.AVATAR);
if (!valid.includes(avatar)) avatar = '';
if (!avatar) {
  if (style === 'cartoon' || style === '2d' || style === '3d') avatar = male ? 'cartoon-boy-1' : 'cartoon-girl-1';
  else if (style === 'presenter' || style === 'podcast') avatar = male ? 'boy-1' : 'girl-1';
}
if (style === 'documentary') avatar = '';
const plan = JSON.parse(base.plan_json);
plan.style = style;
plan.avatar = avatar;
