const extract = (res) => {
  if (res && Array.isArray(res.scenes)) return res;
  let raw = res?.choices?.[0]?.message?.content ?? res?.content?.parts?.[0]?.text ?? res?.parts?.[0]?.text ?? res?.text ?? res?.output ?? '';
  if (typeof raw !== 'string') raw = JSON.stringify(raw);
  raw = raw.split('```json').join('').split('```').join('').trim();
  try { return JSON.parse(raw); } catch (e) {
    const found = [];
    const re = /[{][^{}]*"narration"[^{}]*[}]/g;
    let m;
    while ((m = re.exec(raw)) !== null) { try { found.push(JSON.parse(m[0])); } catch (_) {} }
    const pick = (k) => { const x = raw.match(new RegExp('"' + k + '"\\s*:\\s*"((?:[^"\\\\]|\\\\.)*"')); return x ? x[1] : ''; };
    return { title: pick('title'), thumbnail_text: pick('thumbnail_text'), language: pick('language') || 'en', music_mood: pick('music_mood'), scenes: found };
  }
};
const a = extract($('Write script').first().json) || {};
const b = extract($input.first().json) || {};
const scenes = [].concat(a.scenes || [], b.scenes || []);
const cfg = $('Video settings').first().json;
if (scenes.length < Math.max(3, Math.ceil((Number(cfg.scene_count) || 0) * 0.8))) {
  throw new Error('Merged script has ' + scenes.length + ' of ' + cfg.scene_count + ' scenes (a half was cut off). It will retry on the next run.');
}
return [{ json: Object.assign({}, a, { scenes }) }];

// Per-scene repair pass: every scene gets keywords, alt_keywords, image_prompt.
const j = $json;
const words = (s) => String(s || '').toLowerCase().replace(/[^a-z0-9\u0980-\u09ff ]/g, ' ').split(/\s+/).filter(w => w.length > 3 && !['this','that','with','from','they','them','have','been','will','your','into','also','about','which','their','there','these','those','when','while','very','much','more','most','some','just','like','make','made','take','took','over','than','then','because'].includes(w));
const narr = String(j.narration || (j.lines || []).map(l => l.text).join(' ') || '').trim();
const title = String($('Parse script').first().json.title || '');
if (!narr) { throw new Error('QA 1: scene ' + $itemIndex + ' has no narration at all - script is broken'); }
if (!j.keywords || !String(j.keywords).trim()) j.keywords = words(narr).slice(0, 6).join(' ') || words(title).slice(0, 4).join(' ');
if (!j.alt_keywords || !String(j.alt_keywords).trim()) j.alt_keywords = words(narr).slice(6, 11).join(' ') || words(title).slice(0, 4).join(' ');
if (!j.image_prompt || !String(j.image_prompt).trim()) j.image_prompt = narr.slice(0, 300);
j.keywords = String(j.keywords).slice(0, 120);
j.alt_keywords = String(j.alt_keywords).slice(0, 120);
j.image_prompt = String(j.image_prompt).slice(0, 400);
return { json: j };

// Rebuild the curator input and always offer the AI-image option per scene.
const scenes = $('QA 1: fix scenes').all();
const base = $input.first().json;
const pool = base.pool || [];
const photos = base.photos || [];
const curator_input = scenes.map((s, i) => {
  const vLines = (pool[i] || []).map((c, j) => '  V' + j + ') ' + c.tags.slice(0, 80) + ' | ' + Math.round(c.dur) + 's video (' + c.src + ')');
  const pLines = (photos[i] || []).map((c, j) => '  P' + j + ') ' + c.tags.slice(0, 80) + ' | photo (' + c.src + ')');
  const hasVisual = vLines.length || pLines.length;
  const aiLine = '  A) AI-GENERATED IMAGE: "' + String(s.json.image_prompt || s.json.narration || '').slice(0, 90) + '" (renderer will create it)';
  return 'SCENE ' + i + ': ' + String(s.json.narration).slice(0, 220) + '\n' +
    (vLines.length ? vLines.join('\n') : '  (no video candidates)') + '\n' +
    (pLines.length ? pLines.join('\n') : '  (no photo candidates)') +
    (hasVisual ? '\n' + aiLine + '  <- fallback if nothing above fits' : '\n' + aiLine + '  <- ONLY option, but a good one');
}).join('\n\n');
return [{ json: { pool, photos, curator_input, scene_count: scenes.length } }];

// Last gate before GitHub: the plan must be render-ready.
const base = $input.first().json;
const plan = JSON.parse(base.plan_json);
const HOST_OK = /(^|\.)((videos|images)\.pexels\.com|pexels\.com|cdn\.pixabay\.com|pixabay\.com|(upload|commons)\.wikimedia\.org|wikipedia\.org|image\.pollinations\.ai)$/i;
const scenes = plan.scenes || [];
const errors = [];
if (!scenes.length) errors.push('plan has no scenes');
if (!plan.title) plan.title = 'Untitled video';
if (!plan.style) plan.style = 'documentary';
let stockUrls = 0, aiScenes = 0, fixedUrls = 0;
scenes.forEach((s, i) => {
  const hasVoice = (s.lines && s.lines.length) || String(s.narration || '').trim();
  if (!hasVoice) errors.push('scene ' + i + ' has no narration/dialogue');
  if (Array.isArray(s.footage)) {
    const ok = s.footage.filter(u => { try { return HOST_OK.test(new URL(u).hostname); } catch (e) { return false; } });
    if (ok.length < s.footage.length) { fixedUrls += s.footage.length - ok.length; s.footage = ok; }
    stockUrls += ok.length;
  }
  if (!s.image_prompt || !String(s.image_prompt).trim()) s.image_prompt = String(s.narration || '').slice(0, 300);
  if (!Array.isArray(s.footage) || !s.footage.length) aiScenes++;
});
if (errors.length) throw new Error('QA 3 blocked render: ' + errors.slice(0, 3).join(' | '));
console.log('QA 3: scenes=' + scenes.length + ' stock-urls=' + stockUrls + ' ai-fallback-scenes=' + aiScenes + ' removed-bad-urls=' + fixedUrls);
const plan_json = JSON.stringify(plan);
if (plan_json.length > 62000) throw new Error('Plan too large for GitHub dispatch: ' + plan_json.length);
return [{ json: { ...base, plan_json } }];

// Verify the rendered file is a real video, not a broken/empty download.
const item = $input.first();
const b = item.binary && item.binary.video;
if (!b) throw new Error('QA 4: no video file received from GitHub');
let size = Number(b.fileSize || 0);
if (!size && b.data) size = Math.floor((b.data.length * 3) / 4) - 2;
const mb = size / (1024 * 1024);
if (mb < 1) throw new Error('QA 4: output file too small (' + mb.toFixed(2) + ' MB) - render probably failed');
console.log('QA 4: output OK, ' + mb.toFixed(1) + ' MB');
return item;

